         */externalAddressWords: String?, 
        /**
         * Port number if networking is active
         */port: UInt16?, 
        /**
         * Our four-word user identity
         */fourWords: String, 
        /**
         * Whether we're in local-only mode (no WAN connectivity)
         */isLocalOnlyMode: Bool) {
        self.isActive = isActive
        self.connectionIdentity = connectionIdentity
        self.listenAddress = listenAddress
        self.externalAddress = externalAddress
