// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Events emitted during calls
 */

public enum SwiftCallEvent {
    
    /**
     * Incoming call from another peer
     */
    case incomingCall(callId: String, fromFourWords: String, hasVideo: Bool
    )
    /**
     * Call has been initiated (outgoing)
     */
    case callInitiated(callId: String, toFourWords: String
    )
    /**
     * Call connection established
     */
    case callConnected(callId: String
    )
    /**
     * Call was rejected by the remote peer
     */
    case callRejected(callId: String
    )
    /**
     * Call has ended
     */
    case callEnded(callId: String
    )
    /**
     * Remote peer toggled their video
     */
    case remoteVideoChanged(callId: String, enabled: Bool
    )
    /**
     * Remote peer toggled their audio
     */
    case remoteAudioChanged(callId: String, enabled: Bool
    )
    /**
     * Remote peer started/stopped screen share
     */
    case remoteScreenShareChanged(callId: String, active: Bool
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSwiftCallEvent: FfiConverterRustBuffer {
    typealias SwiftType = SwiftCallEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwiftCallEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .incomingCall(callId: try FfiConverterString.read(from: &buf), fromFourWords: try FfiConverterString.read(from: &buf), hasVideo: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .callInitiated(callId: try FfiConverterString.read(from: &buf), toFourWords: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .callConnected(callId: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .callRejected(callId: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .callEnded(callId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .remoteVideoChanged(callId: try FfiConverterString.read(from: &buf), enabled: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .remoteAudioChanged(callId: try FfiConverterString.read(from: &buf), enabled: try FfiConverterBool.read(from: &buf)
        )
        
        case 8: return .remoteScreenShareChanged(callId: try FfiConverterString.read(from: &buf), active: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SwiftCallEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .incomingCall(callId,fromFourWords,hasVideo):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(callId, into: &buf)
            FfiConverterString.write(fromFourWords, into: &buf)
            FfiConverterBool.write(hasVideo, into: &buf)
            
        
        case let .callInitiated(callId,toFourWords):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(callId, into: &buf)
            FfiConverterString.write(toFourWords, into: &buf)
            
        
        case let .callConnected(callId):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(callId, into: &buf)
            
        
        case let .callRejected(callId):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(callId, into: &buf)
            
        
        case let .callEnded(callId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(callId, into: &buf)
            
        
        case let .remoteVideoChanged(callId,enabled):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(callId, into: &buf)
            FfiConverterBool.write(enabled, into: &buf)
            
        
        case let .remoteAudioChanged(callId,enabled):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(callId, into: &buf)
            FfiConverterBool.write(enabled, into: &buf)
            
        
        case let .remoteScreenShareChanged(callId,active):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(callId, into: &buf)
            FfiConverterBool.write(active, into: &buf)
            
        }
    }
}


